const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  Header, Footer, AlignmentType, LevelFormat, HeadingLevel, BorderStyle,
  WidthType, ShadingType, VerticalAlign, PageNumber, PageBreak, TabStopType, TabStopPosition
} = require("docx");

// ---- Palette ----
const INK   = "26221F";   // warm near-black
const GOLD  = "A67C42";   // refined antique gold
const SOFT  = "8A8178";   // muted taupe
const FILL  = "F4ECE0";   // champagne table header
const RULE  = "DCD3C6";   // light rule
const CW = 9360;          // content width (US Letter, 1in margins)

// ---- Helpers ----
const goldRule = (before = 80, after = 160) => new Paragraph({
  spacing: { before, after },
  border: { bottom: { style: BorderStyle.SINGLE, size: 10, color: GOLD, space: 1 } },
  children: [new TextRun({ text: "", size: 2 })],
});

const h1 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_1,
  spacing: { before: 320, after: 60 },
  children: [new TextRun({ text })],
});

const h2 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  spacing: { before: 220, after: 60 },
  children: [new TextRun({ text })],
});

const body = (text, opts = {}) => new Paragraph({
  spacing: { after: 140, line: 288 },
  children: [new TextRun({ text, ...opts })],
});

const bullet = (text) => new Paragraph({
  numbering: { reference: "bullets", level: 0 },
  spacing: { after: 90, line: 276 },
  children: [new TextRun({ text })],
});

const numbered = (text) => new Paragraph({
  numbering: { reference: "steps", level: 0 },
  spacing: { after: 90, line: 276 },
  children: [new TextRun({ text })],
});

const label = (text) => new Paragraph({
  spacing: { after: 40 },
  children: [new TextRun({ text, font: "Arial", size: 16, bold: true, color: GOLD, characterSpacing: 60 })],
});

// ---- Comp tables ----
const tBorder = { style: BorderStyle.SINGLE, size: 1, color: RULE };
const tBorders = { top: tBorder, bottom: tBorder, left: tBorder, right: tBorder };
const COLS = [4760, 1700, 2900];

function cell(content, { header = false, widthIdx = 0, align = AlignmentType.LEFT, bold = false } = {}) {
  return new TableCell({
    borders: tBorders,
    width: { size: COLS[widthIdx], type: WidthType.DXA },
    shading: header ? { fill: FILL, type: ShadingType.CLEAR, color: "auto" } : undefined,
    margins: { top: 90, bottom: 90, left: 130, right: 130 },
    verticalAlign: VerticalAlign.CENTER,
    children: [new Paragraph({
      alignment: align,
      children: [new TextRun({
        text: content,
        font: "Arial",
        size: header ? 18 : 19,
        bold: header || bold,
        color: header ? INK : INK,
      })],
    })],
  });
}

function compTable(rows) {
  const headerRow = new TableRow({
    tableHeader: true,
    children: [
      cell("Revenue Source", { header: true, widthIdx: 0 }),
      cell("Referral Rate", { header: true, widthIdx: 1, align: AlignmentType.CENTER }),
      cell("Basis", { header: true, widthIdx: 2 }),
    ],
  });
  const dataRows = rows.map(r => new TableRow({
    children: [
      cell(r[0], { widthIdx: 0 }),
      cell(r[1], { widthIdx: 1, align: AlignmentType.CENTER, bold: true }),
      cell(r[2], { widthIdx: 2 }),
    ],
  }));
  return new Table({
    width: { size: CW, type: WidthType.DXA },
    columnWidths: COLS,
    rows: [headerRow, ...dataRows],
  });
}

// ====================== DOCUMENT ======================
const doc = new Document({
  creator: "The Luxora Collective",
  title: "Partnership Proposal: The Luxora Collective and Lucibé",
  styles: {
    default: { document: { run: { font: "Arial", size: 21, color: INK } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { font: "Georgia", size: 28, bold: true, color: INK },
        paragraph: { spacing: { before: 320, after: 60 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { font: "Georgia", size: 23, bold: true, color: INK },
        paragraph: { spacing: { before: 220, after: 60 }, outlineLevel: 1 } },
    ],
  },
  numbering: {
    config: [
      { reference: "bullets", levels: [{ level: 0, format: LevelFormat.BULLET, text: "\u2022",
        alignment: AlignmentType.LEFT, style: { run: { color: GOLD }, paragraph: { indent: { left: 460, hanging: 260 } } } }] },
      { reference: "steps", levels: [{ level: 0, format: LevelFormat.DECIMAL, text: "%1.",
        alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 460, hanging: 260 } } } }] },
    ],
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 },
      },
    },
    headers: {
      default: new Header({ children: [new Paragraph({
        alignment: AlignmentType.RIGHT,
        children: [new TextRun({ text: "THE LUXORA COLLECTIVE", font: "Arial", size: 14, color: SOFT, characterSpacing: 80 })],
      })] }),
    },
    footers: {
      default: new Footer({ children: [new Paragraph({
        tabStops: [{ type: TabStopType.RIGHT, position: TabStopPosition.MAX }],
        children: [
          new TextRun({ text: "theluxoracollective.co", font: "Arial", size: 16, color: SOFT }),
          new TextRun({ text: "\t", font: "Arial", size: 16, color: SOFT }),
          new TextRun({ text: "Page ", font: "Arial", size: 16, color: SOFT }),
          new TextRun({ children: [PageNumber.CURRENT], font: "Arial", size: 16, color: SOFT }),
        ],
      })] }),
    },
    children: [
      // ---------- Title block ----------
      new Paragraph({ spacing: { before: 480, after: 0 },
        children: [new TextRun({ text: "THE LUXORA COLLECTIVE", font: "Arial", size: 20, bold: true, color: GOLD, characterSpacing: 140 })] }),
      goldRule(60, 260),
      new Paragraph({ spacing: { after: 40 },
        children: [new TextRun({ text: "Partnership Proposal", font: "Georgia", size: 52, bold: true, color: INK })] }),
      new Paragraph({ spacing: { after: 260 },
        children: [new TextRun({ text: "The Luxora Collective and Lucib\u00e9", font: "Georgia", size: 30, color: SOFT })] }),
      new Paragraph({ spacing: { after: 360 },
        children: [new TextRun({ text: "An exclusive back bar and skincare education partnership for independent med spas.", font: "Arial", size: 22, italics: true, color: INK })] }),

      label("PREPARED FOR"),
      body("Donna Scott and the Lucib\u00e9 Team", { font: "Arial", size: 22 }),
      label("PREPARED BY"),
      body("Bethany Anne, Co-Founder and Chief Executive Officer, The Luxora Collective", { font: "Arial", size: 22 }),
      label("DATE"),
      body("June 2026", { font: "Arial", size: 22 }),

      new Paragraph({ children: [new PageBreak()] }),

      // ---------- The Opportunity ----------
      h1("The Opportunity"),
      goldRule(),
      body("Most med spa owners did not open their doors to run a business. They opened because they believe in the work, in the moment a client looks in the mirror after a treatment and recognizes herself again. The business side is the part that quietly wears them down. They watch revenue leave through gaps they cannot see: the product sitting on a shelf that no provider ever recommends, the back bar that goes unused, the client who finishes a service and never hears what to do next."),
      body("Lucib\u00e9 and The Luxora Collective solve two halves of the same problem. Lucib\u00e9 gives a med spa a luxury line the provider is proud to use, along with the education to turn each service into recurring revenue. Luxora finds the revenue already trapped inside the business and builds the systems, the memberships, the packages, the sales training, and the marketing that keep it flowing. Together, the owner does not just stock a beautiful product. She sells it, subscribes clients to it, and brings them back for it."),
      body("This proposal outlines how the two companies work together, how each introduces the other to its clients, and a referral compensation plan built to reward both sides fairly for the accounts they bring and continue to support."),

      // ---------- Why we belong together ----------
      h1("Why Luxora and Lucib\u00e9 Belong Together"),
      goldRule(),
      body("The alignment is simple. Both companies are built on the same conviction: the revenue is already inside the med spa, and the work is helping the owner reach it. Lucib\u00e9 does not sell product education alone. It teaches the provider how to generate revenue from the service, retain the client, and convert that client into a subscriber. Luxora does not sell marketing alone. It repairs the foundation first, then installs the full engine that makes every client a lifetime value client."),
      body("Neither company competes with the other. Lucib\u00e9 owns the skincare expertise and the luxury line. Luxora owns the business systems and the owner relationship. The partnership keeps each in its lane and lets each make the other stronger."),

      // ---------- What Lucibé Brings ----------
      h1("What Lucib\u00e9 Brings to the Partnership"),
      goldRule(),
      bullet("A professional aesthetic back bar built around the Lucib\u00e9 line, paired with provider education rather than product education alone."),
      bullet("Four revenue streams created for every provider: the service itself, the recommended product sale, the recurring subscription, and the return visit."),
      bullet("A certification that teaches the three tiers most brands ignore: how to perform and present the service, how to retain the client, and how to convert clients into subscribers."),
      bullet("A ready-made provider recommendation sheet that removes the sales barrier for estheticians who are not comfortable selling, so the owner knows each step is being followed."),
      bullet("Full fulfillment support. Accounts are not required to package or ship. Clients scan a QR code, subscribe, and receive product directly, while the provider still earns on the sale and carries no inventory burden."),
      bullet("No order minimums, which removes the heavy upfront stock commitment that has hurt providers under other brands."),
      bullet("Law-compliant featured brands where state regulations require them, including a dedicated sunscreen line for states with stricter rules."),
      bullet("A founder with more than a decade of private consulting experience and national recognition in the skincare field."),

      // ---------- What Luxora Brings ----------
      h1("What Luxora Brings to the Partnership"),
      goldRule(),
      bullet("A qualified base of established med spa owners, generally between 500 thousand and 2 million dollars in annual revenue, who have already completed a Revenue Leak Audit and Market Blueprint, so the foundation is set before any new line is introduced."),
      bullet("A trusted advisory relationship. When Luxora professionally recommends a line, owners act on it."),
      bullet("Integration of Lucib\u00e9 into the Growth Engine, the membership and package architecture, and the staff sales training, so the line is not simply stocked, it is sold."),
      bullet("A growing community of clients on bi-weekly calls and an online course, with a standing platform for Donna to appear as the skincare authority."),
      bullet("Ongoing marketing, accountability, and monthly check-ins that keep referred accounts active and growing, which directly protects the recurring revenue Lucib\u00e9 earns from them."),

      // ---------- How Luxora presents Lucibé ----------
      new Paragraph({ children: [new PageBreak()] }),
      h1("How Luxora Presents Lucib\u00e9 to Clients"),
      goldRule(),
      body("Lucib\u00e9 is never white-labeled. The name stays luxury and exclusive, because the value to the owner is in the prestige of recommending a line that not everyone has. Luxora positions Lucib\u00e9 as the exclusive, professionally recommended back bar and skincare line within the Growth Engine."),
      bullet("The line is introduced after the Revenue Leak Audit and Market Blueprint, once the foundation is solid, as the owner's luxury skincare moment and a clear point of differentiation in her market."),
      bullet("Positioning leads with the owner's standing. This is the line you use in service, recommend with conviction, and subscribe your clients to, because you believe in it enough to put it on every face."),
      bullet("The provider recommendation sheet makes the sale effortless: select the service, present the professionally recommended regimen, book the next visit at thirty days, and offer the subscription."),
      bullet("Demos sit on the shelf, the back bar stays in active use, and the QR subscription handles fulfillment, so the owner carries no inventory risk and still earns on every sale."),
      bullet("Donna joins a Luxora community call as the guest skincare expert, reviewing real cases and showing owners how to generate revenue from the service, not only from the shelf."),
      body("Within the value ladder, Lucib\u00e9 becomes the natural luxury upgrade an owner reaches for once memberships and packages are in place, a differentiator that helps a stuck med spa stand out rather than blend in with the twelve lines already on every competitor's shelf."),

      // ---------- How Lucibé presents Luxora ----------
      h1("How Lucib\u00e9 Presents Luxora to Their Network"),
      goldRule(),
      body("Lucib\u00e9 introduces Luxora as the growth partner that recovers the revenue already inside a med spa, the revenue lost to untrained front desks, unconverted consultations, stagnant clients, weak packages, and missing memberships."),
      bullet("The introduction flows naturally into Lucib\u00e9's existing relationships and its expanding network as the back bar program scales."),
      bullet("The framing is simple and complementary: Lucib\u00e9 makes the skincare and the education exceptional, and Luxora makes the entire business generate."),
      bullet("Luxora opens every referred relationship with the Revenue Leak Audit, the same low-risk entry point that earns owner trust before any larger investment is recommended."),
      bullet("Every introduction is warm. Lucib\u00e9 is not handing off a name, it is recommending a partner that protects and grows the same accounts it serves."),

      // ---------- Exclusivity ----------
      h1("The Exclusivity Framework"),
      goldRule(),
      body("Luxury is defined by the fact that everybody does not have it. This partnership is built to protect that."),
      bullet("Luxora clients gain access to Lucib\u00e9 as the recommended exclusive line because of this relationship."),
      bullet("Lucib\u00e9 preserves its luxury positioning. The line is not distributed broadly through this channel, which protects the prestige that makes owners want it in the first place."),
      bullet("Accounts that approach Lucib\u00e9 outside this relationship are engaged at Lucib\u00e9's standard rate. The relationship is the privilege, and it is reserved."),

      // ---------- Referral Compensation Plan ----------
      new Paragraph({ children: [new PageBreak()] }),
      h1("Referral Compensation Plan"),
      goldRule(),
      body("The compensation is built to be fair on both ends. Each party brings the other qualified, pre-warmed accounts and continues to support them after the introduction, so the structure rewards ongoing performance rather than a single handoff. The two directions mirror each other, and the rate is identical in both, which keeps the arrangement clean and easy to trust."),

      h2("Luxora Compensation, Paid by Lucib\u00e9"),
      body("Earned on every med spa that Luxora introduces to Lucib\u00e9. Because Luxora continues to market to and support these accounts, the override is recurring, which keeps both companies invested in the account's long-term growth.", { size: 19, color: SOFT }),
      compTable([
        ["Initial back bar onboarding order", "10%", "One time, on the first order"],
        ["Ongoing wholesale and retail product revenue", "10%", "Life of the active account"],
        ["Subscription revenue", "10%", "Life of each active subscription"],
        ["Lucib\u00e9 certification or education fee", "10%", "Per enrollment"],
      ]),

      h2("Lucib\u00e9 Compensation, Paid by Luxora"),
      body("Earned on every med spa that Lucib\u00e9 introduces to Luxora that becomes a client. The structure mirrors the Luxora side at the same rate, so the value exchange stays balanced in both directions.", { size: 19, color: SOFT }),
      compTable([
        ["Luxora 90-day Growth Engine engagement", "10%", "First engagement, per referred account"],
        ["Luxora ongoing marketing retainer", "10%", "First twelve months of retainer"],
      ]),

      h2("Attribution and Payment Terms"),
      bullet("Each referred account is registered by name in a shared referral log at the time of introduction, so attribution is never in question."),
      bullet("Referral compensation is calculated on net revenue actually collected, after refunds and returns."),
      bullet("Payments are reconciled and paid monthly, net thirty days, with a simple statement listing the accounts and amounts."),
      bullet("An account remains attributed to the referring party for as long as it stays active under this partnership."),
      bullet("The ten percent rate is the agreed starting point. As volume grows, either party may propose revisiting it, and any change applies only going forward."),

      // ---------- Operating Rhythm ----------
      h1("Operating Rhythm"),
      goldRule(),
      bullet("A short monthly check-in between Bethany and Donna to review active accounts, upcoming introductions, and any product or education updates."),
      bullet("A standing invitation for Donna to appear on Luxora community calls as the skincare authority."),
      bullet("Aanchal coordinates referral registration, partnership agreements, and onboarding on the Luxora side, so introductions move quickly and nothing is dropped."),

      // ---------- Next Steps ----------
      h1("Next Steps"),
      goldRule(),
      numbered("Confirm the compensation structure and the exclusivity terms outlined above."),
      numbered("Formalize the arrangement in a short partnership agreement."),
      numbered("Register the first wave of Luxora accounts, beginning with the initial group currently in bi-weekly calls, for Lucib\u00e9 introductions."),
      numbered("Schedule Donna's first appearance on a Luxora community call as the guest skincare expert."),
      numbered("Open reciprocal introductions from Lucib\u00e9's network into the Luxora Revenue Leak Audit."),

      goldRule(280, 120),
      new Paragraph({ spacing: { before: 60, after: 20 },
        children: [new TextRun({ text: "The Luxora Collective", font: "Georgia", size: 22, bold: true, color: INK })] }),
      new Paragraph({ spacing: { after: 20 },
        children: [new TextRun({ text: "Bethany Anne, Co-Founder and Chief Executive Officer", font: "Arial", size: 19, color: INK })] }),
      new Paragraph({ spacing: { after: 0 },
        children: [new TextRun({ text: "theluxoracollective.co", font: "Arial", size: 19, color: GOLD })] }),
    ],
  }],
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync("/home/claude/Luxora_Lucibe_Partnership_Proposal.docx", buffer);
  console.log("written");
});

